// ErrChatPathEmpty says "The chat has no session file"
// in the language the app shows.
func ErrChatPathEmpty() string { return In(i18n.Locale()).ErrChatPathEmpty() }

// ErrChatPathEmpty says "The chat has no session file"
// in the language of msgs.
